import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/AUTORECODE.md","filePath":"manual-zh/AUTORECODE.md","lastUpdated":1785684581000}'),r={name:"manual-zh/AUTORECODE.md"};function n(c,t,i,s,p,l){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h3 id="_12-2-autorecode" tabindex="-1">12.2 AUTORECODE <a class="header-anchor" href="#_12-2-autorecode" aria-label="Permalink to &quot;12.2 AUTORECODE&quot;">​</a></h3><pre><code>AUTORECODE VARIABLES=src_vars INTO dest_vars
        [ /DESCENDING ]
        [ /PRINT ]
        [ /GROUP ]
        [ /BLANK = {VALID, MISSING} ]
</code></pre><p><code>AUTORECODE</code> 过程考虑一个变量所取的 n 个值，并将它们映射到新数值变量上的值 1…n。</p><p><code>VARIABLES</code> 子命令是唯一必需的子命令，且必须排在第一位。指定 <code>VARIABLES</code>、等号（‘=’）、源变量列表、<code>INTO</code>，以及目标变量列表。源变量和目标变量的数量必须相同。目标变量必须尚未存在。</p><p><code>AUTORECODE</code> 通常将源变量的每个递增的非缺失值（对于字符串，基于字符编码比较）赋给其目标变量的连续取值。例如，源变量的最小非缺失值被重编码为 1，次小的为 2，依此类推。如果源变量有用户缺失值，它们会被重编码为紧接在非缺失值之上的连续取值。例如，如果源变量有七个不同的非缺失值，则最小的缺失值会被重编码为 8，次小的为 9，依此类推。</p><p>使用 <code>DESCENDING</code> 可反转非缺失值的排序顺序，使最大的非缺失值被重编码为 1，第二大为 2，依此类推。即使使用 <code>DESCENDING</code>，用户缺失值仍按升序重编码为紧接在非缺失值之上的取值。</p><p>系统缺失值总是被重编码为目标变量中的系统缺失值。</p><p>如果源值有值标签，则该值标签会保留给目标变量中的新值。否则，源值本身成为每个新值的标签。</p><p>变量标签从源变量复制到目标变量。</p><p><code>PRINT</code> 当前被忽略。</p><p><code>GROUP</code> 子命令仅当要对多个变量重编码时相关。它使源值与目标值之间使用单一的映射，而不是每个变量各用一张映射表。使用 <code>GROUP</code> 时，用户缺失值取自第一个含有任何用户缺失值的源变量。</p><p>如果给定 <code>/BLANK=MISSING</code>，则仅包含空白的字符串变量被重编码为 SYSMIS。如果指定 <code>/BLANK=VALID</code>，则它们像其他值一样被分配一个取值。<code>/BLANK</code> 与数值无关。<code>/BLANK=VALID</code> 为默认值。</p><p><code>AUTORECODE</code> 是一个过程。它会导致数据被读取。它会忽略 <code>TEMPORARY</code>（参见 <a href="./TEMPORARY">TEMPORARY</a>），因此“临时”转换会变成永久转换。</p><h4 id="_12-2-1-自动重编码示例" tabindex="-1">12.2.1 自动重编码示例 <a class="header-anchor" href="#_12-2-1-自动重编码示例" aria-label="Permalink to &quot;12.2.1 自动重编码示例&quot;">​</a></h4><p>在文件 personnel.sav 中，变量 <strong>occupation</strong> 是一个字符串变量。除纯注释性质的数据外，字符串变量通常不是一个好选择。原因之一是数据录入错误很容易被忽略。这在 personnel.sav 中就发生了：本应录入“Scientist”的一项被误录为“Scrientist”。在示例 12.2 中，首先通过 <code>DO IF</code> 子句纠正该错误（3），然后使用 <code>AUTORECODE</code> 创建一个新数值变量，其取值为 <strong>occupation</strong> 的重编码值。最后，删除旧变量，并将新变量重命名为旧变量的名称。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;personnel.sav&#39;.  * Correct a typing error in the original file. do if occupation = &quot;Scrientist&quot;.  compute occupation = &quot;Scientist&quot;. end if.  autorecode 	variables = occupation into occ 	/blank = missing.  * Delete the old variable. delete variables occupation.  * Rename the new variable to the old variable&#39;s name. rename variables (occ = occupation).  * Inspect the new variable. display dictionary /variables=occupation.</span></span></code></pre></div><p><strong>示例 12.2：</strong> 在纠正数据录入错误后，使用 <code>AUTORECODE</code> 将字符串变量转换为数值变量</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 12.1：</strong> 自动重编码对话框，设置为将 <strong>occupation</strong> 重编码为 <strong>occ</strong></p><p>注意在结果 12.1 中，新变量已被自动分配了与旧变量字符串相对应的取值标签。这意味着在未来的分析中，会报告这些描述性字符串，而不是数值。</p><table tabindex="0"><thead><tr><th>Name</th><th>Position</th><th>Measurement Level</th><th>Role</th><th>Width</th><th>Alignment</th><th>Print Format</th><th>Write Format</th></tr></thead><tbody><tr><td>occupation</td><td>6</td><td>Unknown</td><td>Input</td><td>8</td><td>Right</td><td>F2.0</td><td>F2.0</td></tr><tr><td>Variable Value</td><td>Label</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>occupation</td><td>1</td><td>Artist</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Baker</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>Barrister</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td>Carpenter</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td>Cleaner</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td>Cook</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td>Manager</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td>Mathematician</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td>Painter</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td>Payload Specialist</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td>Plumber</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td>Scientist</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>13</td><td>Tailor</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>结果 12.1：</strong> <code>AUTORECODE</code> 之后 <strong>occupation</strong> 变量的属性</p><h4 id="脚注" tabindex="-1">脚注 <a class="header-anchor" href="#脚注" aria-label="Permalink to &quot;脚注&quot;">​</a></h4><h5 id="_3" tabindex="-1">(3) <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;(3)&quot;">​</a></h5><p>在纠正此类数据录入错误时，必须谨慎，而不是简单地将其标记为缺失。例如，如果某个职业被录入为“Barister”，这个人是指“Barrister”还是指“Barista”？</p>`,25)])])}const E=d(r,[["render",n]]);export{u as __pageData,E as default};
